Preparing the data
For each country, I use its most recent observation and calculate the difference between its pre-tax and post-tax Gini coefficients.

latest_inequality &lt;- income_inequality |&gt;
  filter(
    !is.na(Code),
    !is.na(gini_mi_eq),
    !is.na(gini_dhi_eq)
  ) |&gt;
  group_by(Entity) |&gt;
  slice_max(Year, n = 1, with_ties = FALSE) |&gt;
  ungroup() |&gt;
  mutate(
    inequality_reduction = gini_mi_eq - gini_dhi_eq
  )

top_reducers &lt;- latest_inequality |&gt;
  slice_max(inequality_reduction, n = 15)
